class TypeEnvironment:
    """A mutable map from SSA values (and their names) to types."""

    def __init__(self) -> None:
        self._by_value: Dict[int, TypeBinding] = {}
        self._by_name: Dict[str, TypeBinding] = {}

    # -- mutation ---------------------------------------------------------
    def bind(self, binding: TypeBinding) -> TypeBinding:
        if binding.value is not None:
            self._by_value[id(binding.value)] = binding
        if binding.key:
            self._by_name[binding.key] = binding
        return binding

    # -- lookup -----------------------------------------------------------
    def lookup_value(self, value: Value) -> Optional[TypeBinding]:
        found = self._by_value.get(id(value))
        if found is not None:
            return found
        name = getattr(value, "name", None)
        return self._by_name.get(name) if name else None

    def lookup(self, key: Any) -> Optional[TypeBinding]:
        if isinstance(key, Value):
            return self.lookup_value(key)
        if isinstance(key, str):
            direct = self._by_name.get(key)
            if direct is not None:
                return direct
            # Accept both ``name`` and ``scope::name``.
            suffix = "::" + key
            for stored, binding in self._by_name.items():
                if stored.endswith(suffix):
                    return binding
        return None

    def type_of(self, key: Any) -> Optional[Type]:
        binding = self.lookup(key)
        return binding.type if binding is not None else None

    def width(self, key: Any) -> int:
        binding = self.lookup(key)
        return binding.width if binding is not None else 0

    def sort(self, key: Any) -> Sort:
        binding = self.lookup(key)
        return binding.sort if binding is not None else Sort.UNKNOWN

    # -- views -------------------------------------------------------------
    @property
    def bindings(self) -> List[TypeBinding]:
        seen: Dict[int, TypeBinding] = {}
        for binding in list(self._by_value.values()) + list(self._by_name.values()):
            seen[id(binding)] = binding
        return list(seen.values())

    def names(self) -> List[str]:
        return sorted(self._by_name)

    def __len__(self) -> int:
        return len(self.bindings)

    def __contains__(self, key: Any) -> bool:
        return self.lookup(key) is not None


@dataclass
class TypeResolution:
    """The result of running :class:`TypeResolver`."""

    environment: TypeEnvironment = field(default_factory=TypeEnvironment)
    conflicts: List[TypeConflict] = field(default_factory=list)
    signatures: Dict[str, FunctionType] = field(default_factory=dict)
